		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			traceExpOnce = sync.Once{}
			exp, expFunc, err := getTraceExporter(context.Background(), tt.cfg)
			if tt.wantErr != nil {
